using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace CatGames {
 public sealed class BrawlGame:MiniGame {
  public sealed class Surface {public string id;public float left,right,y;public bool shelf;public Surface(string id,float l,float r,float y,bool shelf=false){this.id=id;left=l;right=r;this.y=y;this.shelf=shelf;}}
  public static readonly Surface[] Surfaces={new Surface("floor",0,1800,0),new Surface("counter",345,1765,-274),new Surface("shelf-left",370,640,-454,true),new Surface("shelf-window",690,990,-460,true),new Surface("shelf-stove",1260,1510,-455,true),new Surface("fridge",72,336,-578),new Surface("cabinet-left",354,586,-662),new Surface("window-top",615,1042,-642),new Surface("cabinet-mid",1072,1298,-662),new Surface("hood",1307,1458,-616),new Surface("cabinet-right",1538,1765,-662)};
  public static readonly Surface[] LivingSurfaces={Surfaces[0],new Surface("l-bookcase-left",71,345,-448),new Surface("l-sofa-back",426,887,-289),new Surface("l-sofa-seat",431,882,-166),new Surface("l-tv",964,1481,-209),new Surface("l-bookcase-right",1517,1755,-507),new Surface("l-shelf-left",374,640,-430),new Surface("l-shelf-mid",977,1196,-479),new Surface("l-shelf-right",1218,1481,-427)};
  public sealed class Fighter {public int id,hp=100,facing=1,kills,damage,target=-1;public bool targetItem,grounded=true,airGoal;public string color,surfaceId;public float x,y,vx,vy,surface,drop,dropFrom,anim,attack,cooldown,invincible=2.5f,stun,hitPause,flash,shield,power,speed,glove,ice,chilled,feather,retreatUntil,deadTime,think,dir,jumpBuffer,coyote=.1f,land,goalX;public readonly HashSet<int> hit=new HashSet<int>();}
  public sealed class Item {public int id;public string kind;public float x,y;public bool taken;}
  public sealed class HitEffect {public float x,y,age;public bool blocked,power;}
  public readonly List<Fighter> cats=new List<Fighter>();public readonly List<Item> items=new List<Item>();public readonly List<HitEffect> fx=new List<HitEffect>();public string phase="countdown";public readonly string map,difficulty;public readonly Surface[] surfaces;public float countdown=2.5f,remaining=85,camera=500,cameraY,nextItem=4,deathWait;int serial=3;public float ViewZoom=>Mathf.Max(1,CatPaint.ViewHeight/1409);public float MinCameraY=>-1220+(700+CatPaint.Extra/2)/ViewZoom;public float MaxCameraY=>189-(CatPaint.ViewHeight-700-CatPaint.Extra/2)/ViewZoom;
  public BrawlGame(string color,string difficulty="normal",string map="kitchen"){this.difficulty=MatchOptions.Valid(difficulty);this.map=map=="living"?map:"kitchen";surfaces=this.map=="living"?LivingSurfaces:Surfaces;float[] xs={800,250,510,1110,1390,1660};string[] at=this.map=="living"?new[]{"l-sofa-back","l-bookcase-left","l-sofa-seat","l-shelf-mid","l-tv","l-bookcase-right"}:new[]{"counter","fridge","counter","cabinet-mid","shelf-stove","floor"};for(int i=0;i<6;i++){var s=Array.Find(surfaces,p=>p.id==at[i]);cats.Add(new Fighter{id=i,color=i==0?color:CatPaint.Colors[(i-1)%4],x=Clamp(xs[i],s.left+35,s.right-35),y=s.y,surface=s.y,surfaceId=s.id,facing=i%2==1?-1:1,think=.6f+i*.16f});}items.Add(new Item{id=0,kind="shield",x=this.map=="living"?540:380,y=this.map=="living"?-321:-32});items.Add(new Item{id=1,kind="glove",x=this.map=="living"?1080:860,y=this.map=="living"?-511:-492});items.Add(new Item{id=2,kind="ice",x=this.map=="living"?1300:1150,y=this.map=="living"?-241:-694});camera=Clamp(cats[0].x-300,0,1200);cameraY=Clamp(cats[0].y+220,-520,-11);}
  public static bool CanReach(Surface from,Surface to){float disc=1060*1060-2*1850*(from.y-to.y);if(disc<0||from==to)return false;float range=235*(1060+Mathf.Sqrt(disc))/1850-35,gap=Mathf.Max(0,to.left+26-(from.right-26),from.left+26-(to.right-26));return gap<=range;}
  static readonly Dictionary<string,List<string>> routes=new Dictionary<string,List<string>>();
  public static List<string> Route(string from,string to,Surface[] surfaces=null){surfaces=surfaces??Surfaces;if(from==to)return new List<string>();string key=(surfaces==LivingSurfaces?"living:":"kitchen:")+from+":"+to;if(routes.TryGetValue(key,out var cached))return cached;var queue=new Queue<List<string>>();queue.Enqueue(new List<string>{from});var seen=new HashSet<string>{from};while(queue.Count>0){var path=queue.Dequeue();var a=Array.Find(surfaces,p=>p.id==path[path.Count-1]);if(a==null)continue;foreach(var b in surfaces){if(seen.Contains(b.id)||!CanReach(a,b))continue;var next=new List<string>(path){b.id};if(b.id==to){next.RemoveAt(0);routes[key]=next;return next;}seen.Add(b.id);queue.Enqueue(next);}}return new List<string>();}
  Surface Support(float x,float y)=>surfaces.Where(p=>x>p.left&&x<p.right&&p.y>=y-2).OrderBy(p=>p.y).FirstOrDefault()??surfaces[0];
  public static string AttackPhase(Fighter c)=>c.attack>.41f?"windup":c.attack>.18f?"dash":c.attack>0?"recover":"idle";
  public override void Action(string a)=>Act(cats[0],a);
  public bool TryAction(string action)=>Act(cats[0],action);
  bool Act(Fighter c,string a){if(ended||phase!="fight"||c.hp<=0||c.stun>0)return false;
   if(a=="jump"){if(!c.grounded&&c.coyote<=0){c.jumpBuffer=.12f;return false;}c.vy=-1060*(c.feather>0?1.13f:1);c.grounded=false;c.coyote=0;c.y-=.01f;if(c.id==0)Emit("jump");return true;}
   if(a=="drop"){if(!c.grounded||c.surface==0)return false;c.drop=.3f;c.dropFrom=c.surface;c.grounded=false;c.coyote=0;c.y+=5;c.vy=40;return true;}
   if(a=="attack"&&c.cooldown==0&&c.attack==0){c.attack=.53f;c.cooldown=c.glove>0?.78f:1.25f;c.hit.Clear();if(c.id==0)Emit("brawl-charge");return true;}return false;
  }
  public bool Damage(Fighter from,Fighter to){if(to.hp<=0||to.invincible>0||from.hit.Contains(to.id))return false;from.hit.Add(to.id);bool block=to.shield>0;int amount=block?0:from.power>0?32:20;if(block)to.shield=0;else if(from.ice>0)to.chilled=2.2f;from.damage+=Mathf.Min(to.hp,amount);to.hp=Mathf.Max(0,to.hp-amount);to.flash=.16f;to.invincible=.85f;to.stun=.15f;to.hitPause=from.hitPause=.035f;to.vx=from.facing*(block?200:430);to.vy=-180;to.grounded=false;to.attack=0;fx.Add(new HitEffect{x=(from.x+to.x)/2,y=(from.y+to.y)/2-58,blocked=block,power=from.power>0});if(from.id==0||to.id==0)Emit(block?"shield-break":"brawl-hit");if(to.hp==0){from.kills++;Emit("brawl-ko");}return true;}
  public void Take(Fighter c,Item i){if(i.taken||c.hp<=0)return;i.taken=true;if(i.kind=="food")c.hp=Mathf.Min(100,c.hp+32);if(i.kind=="shield")c.shield=12;if(i.kind=="pepper")c.power=9;if(i.kind=="speed")c.speed=7;if(i.kind=="glove")c.glove=9;if(i.kind=="ice")c.ice=9;if(i.kind=="feather")c.feather=8;if(c.id==0)Emit("pickup",i.kind);}
  public string Tactic(Fighter c,Fighter t){if(t==null||c.attack>0)return "chase";float dx=t.x-c.x,distance=Mathf.Abs(dx);if(Mathf.Abs(t.y-c.y)>=72)return "chase";string phase=AttackPhase(t);bool incoming=(phase=="windup"||phase=="dash")&&t.facing*dx<0&&distance<190;if(difficulty!="casual"&&incoming&&c.grounded)return "dodge";if(difficulty=="hard"){if(t.shield>0&&c.shield==0&&distance<145)return "retreat";if(c.cooldown==0&&(phase=="recover"||t.cooldown>.25f)&&distance<175)return "attack";if(c.cooldown>0&&distance<140||phase=="dash")return "retreat";}if(difficulty!="casual"&&(phase=="windup"||phase=="dash"))return "chase";return distance<135&&c.cooldown==0?"attack":"chase";}
  void Bot(Fighter c,float dt){c.think-=dt;bool observe=c.think<=0;if(observe){c.think=.22f+UnityEngine.Random.value*.08f;var target=cats.Where(o=>o!=c&&o.hp>0).OrderBy(o=>Mathf.Abs(o.x-c.x)+Mathf.Abs(o.y-c.y)*.8f-(difficulty=="hard"&&AttackPhase(o)=="recover"?70:0)).FirstOrDefault();var item=items.Where(i=>!i.taken&&(i.kind!="food"||c.hp<75)).OrderBy(i=>Mathf.Abs(i.x-c.x)+Mathf.Abs(i.y-c.y)*.8f).FirstOrDefault();c.targetItem=item!=null&&Mathf.Abs(item.x-c.x)+Mathf.Abs(item.y-c.y)*.8f<340&&(difficulty!="casual"||target==null||Mathf.Abs(target.x-c.x)+Mathf.Abs(target.y-c.y)*.8f>180);c.target=c.targetItem?item.id:target?.id??-1;}
   float tx,ty;Fighter enemy=null;if(c.targetItem){var i=items.Find(o=>o.id==c.target&&!o.taken);if(i==null){c.dir=0;return;}tx=i.x;ty=i.y+32;}else{enemy=cats.Find(o=>o.id==c.target&&o.hp>0);if(enemy==null){c.dir=0;return;}tx=enemy.x;ty=enemy.y;}
   float dx=tx-c.x;c.dir=Mathf.Abs(dx)>48?Mathf.Sign(dx):0;
   if(c.grounded){c.airGoal=false;var from=Support(c.x,c.y);var to=Support(tx,ty);var route=Route(from.id,to.id,surfaces);if(route.Count>0){var next=Array.Find(surfaces,p=>p.id==route[0]);float landing=Clamp(tx,next.left+26,next.right-26),takeoff=Clamp(landing,from.left+26,from.right-26);c.dir=Mathf.Abs(takeoff-c.x)>18?Mathf.Sign(takeoff-c.x):0;if(Mathf.Abs(takeoff-c.x)<=20){c.airGoal=true;c.goalX=landing;c.dir=Mathf.Abs(landing-c.x)>12?Mathf.Sign(landing-c.x):0;if(next.y>from.y&&c.x>next.left+26&&c.x<next.right-26)Act(c,"drop");else Act(c,"jump");}}}else if(c.airGoal)c.dir=Mathf.Abs(c.goalX-c.x)>12?Mathf.Sign(c.goalX-c.x):0;
   if(c.dir!=0&&c.attack==0)c.facing=(int)c.dir;if(enemy!=null&&observe){if(dx!=0)c.facing=(int)Mathf.Sign(dx);string tactic=Tactic(c,enemy);if(tactic=="dodge")Act(c,"jump");if(tactic=="retreat")c.retreatUntil=age+.3f;if(tactic=="attack")Act(c,"attack");}if(c.retreatUntil>age&&c.attack==0)c.dir=-Mathf.Sign(dx);
  }
  public override void Update(float dt,float direction){if(ended)return;float left=Mathf.Min(.1f,dt);while(left>0&&!ended){float sub=Mathf.Min(left,1f/120);Step(sub,direction);left-=sub;}}
  void Step(float dt,float input){age+=dt;foreach(var f in fx)f.age+=dt;fx.RemoveAll(f=>f.age>.35f);if(phase=="countdown"){int old=Mathf.CeilToInt(countdown);countdown=Dec(countdown,dt);if(Mathf.CeilToInt(countdown)!=old)Emit(countdown==0?"race-go":"race-tick");if(countdown==0)phase="fight";return;}time+=dt;remaining=Mathf.Max(0,85-time);
   foreach(var c in cats){if(c.hp<=0){c.deadTime+=dt;continue;}c.cooldown=Dec(c.cooldown,dt);c.invincible=Dec(c.invincible,dt);c.stun=Dec(c.stun,dt);c.flash=Dec(c.flash,dt);c.shield=Dec(c.shield,dt);c.power=Dec(c.power,dt);c.speed=Dec(c.speed,dt);c.glove=Dec(c.glove,dt);c.ice=Dec(c.ice,dt);c.chilled=Dec(c.chilled,dt);c.feather=Dec(c.feather,dt);c.drop=Dec(c.drop,dt);c.jumpBuffer=Dec(c.jumpBuffer,dt);c.land=Dec(c.land,dt);if(c.hitPause>0){c.hitPause=Dec(c.hitPause,dt);continue;}if(c.id>0)Bot(c,dt);else c.dir=Clamp(input,-1,1);c.attack=Dec(c.attack,dt);string phase=AttackPhase(c);
    float movement=(c.speed>0?1.3f:1)*(c.chilled>0?.55f:1);if(phase=="dash")c.vx=c.facing*650*movement;else if(c.stun==0){float target=c.dir*235*movement*(phase=="windup"?.12f:phase=="recover"?.4f:1);c.vx+=(target-c.vx)*(1-Mathf.Exp(-19*dt));if(c.dir!=0&&phase=="idle")c.facing=(int)c.dir;}
    c.x=Clamp(c.x+c.vx*dt,75,1725);c.anim+=dt*Mathf.Max(.3f,Mathf.Abs(c.vx)/235);float oldY=c.y;c.vy+=1850*dt;c.y+=c.vy*dt;c.grounded=false;
    foreach(var s in surfaces.OrderBy(s=>s.y))if(!(c.drop>0&&s.y==c.dropFrom)&&c.vy>=0&&oldY<=s.y+.1f&&c.y>=s.y&&c.x>s.left&&c.x<s.right){c.y=s.y;c.vy=0;c.grounded=true;c.surface=s.y;c.surfaceId=s.id;if(oldY<s.y-1){c.land=.14f;if(c.id==0)Emit("land");}break;}
    c.coyote=c.grounded?.1f:Dec(c.coyote,dt);if(c.grounded&&c.jumpBuffer>0)Act(c,"jump");foreach(var i in items)if(!i.taken&&Mathf.Abs(i.x-c.x)<43&&Mathf.Abs(i.y-(c.y-35))<55)Take(c,i);
   }
   foreach(var a in cats)if(a.hp>0&&AttackPhase(a)=="dash")foreach(var b in cats)if(a!=b&&b.hp>0&&Mathf.Abs(a.x-b.x)<65&&Mathf.Abs(a.y-b.y)<66&&(b.x-a.x)*a.facing>-25)Damage(a,b);
   for(int i=0;i<cats.Count;i++)for(int j=i+1;j<cats.Count;j++){var a=cats[i];var b=cats[j];if(a.hp<=0||b.hp<=0||Mathf.Abs(a.y-b.y)>55||AttackPhase(a)=="dash"||AttackPhase(b)=="dash")continue;float dx=b.x-a.x;if(Mathf.Abs(dx)<45){float push=(45-Mathf.Abs(dx))*.5f*(dx==0?1:Mathf.Sign(dx));a.x=Clamp(a.x-push,75,1725);b.x=Clamp(b.x+push,75,1725);}}
   nextItem-=dt;if(nextItem<=0){nextItem=4;items.RemoveAll(i=>i.taken);if(items.Count<7){var s=surfaces[UnityEngine.Random.Range(0,surfaces.Length)];items.Add(new Item{id=serial++,kind=new[]{"food","shield","pepper","speed","glove","ice","feather"}[(serial-1)%7],x=UnityEngine.Random.Range(s.left+45,s.right-45),y=s.y-32});}}
   camera=Clamp(camera+(cats[0].x-300/ViewZoom-camera)*(1-Mathf.Exp(-8*dt)),0,1800-600/ViewZoom);cameraY=Clamp(cameraY+(cats[0].y+220-cameraY)*(1-Mathf.Exp(-7*dt)),MinCameraY,MaxCameraY);int alive=cats.Count(c=>c.hp>0);rank=cats.OrderByDescending(c=>c.hp>0).ThenByDescending(c=>c.kills).ThenByDescending(c=>c.damage).ThenByDescending(c=>c.hp).ThenBy(c=>c.id).ToList().FindIndex(c=>c.id==0)+1;if(cats[0].hp<=0)deathWait+=dt;if(deathWait>.65f||alive<=1||remaining==0){phase="finish";score=rank;Finish(cats[0].hp>0&&rank==1,"第 "+rank+" 名");}
  }
  public override void Draw(CatPaint p,string color){camera=Clamp(camera,0,1800-600/ViewZoom);cameraY=Clamp(cameraY,MinCameraY,MaxCameraY);p.Rect(0,0,600,900,"#a7e9cf");string room=map=="living"?"brawl-living":"brawl-kitchen";float baseY=700-cameraY;p.Image(room+"-wall",-camera,baseY-1220,1800,510);p.Image(room,-camera,baseY-711,1800,900);foreach(var s in surfaces){if(s.shelf)p.Image("brawl-shelf",s.left-camera,baseY+s.y,s.right-s.left,(s.right-s.left)*p.art["brawl-shelf"].height/p.art["brawl-shelf"].width);else if(s.id!="floor"&&s.id!="counter")p.Line(s.left-camera+12,baseY+s.y+4,s.right-camera-12,baseY+s.y+4,3,"#fff5caaa");}
   foreach(var i in items)if(!i.taken&&i.x>camera-70&&i.x<camera+670)p.Bottom("item-"+i.kind,i.x-camera,baseY+i.y+15+Mathf.Sin(age*2.5f)*4,54);
   foreach(var c in cats.OrderBy(c=>c.id==0)){if(c.x<camera-150||c.x>camera+750||c.hp<=0&&c.deadTime>.6f)continue;float x=c.x-camera,y=baseY+c.y;string phase=AttackPhase(c);int frame=c.hp<=0?15:c.stun>0?2:phase=="windup"?14:phase=="dash"?19:!c.grounded?(c.vy<0?24:25):c.land>0?26:Mathf.Abs(c.vx)>25?Frame("walk",c.anim):Frame("idle",c.anim);
    p.Oval(x,baseY+Support(c.x,c.y).y,60,12,"#3d674c24");if(phase=="dash")CatEffects.Dash(p,x,y,c.facing,1-(c.attack-.18f)/.23f,c.power>0);
    p.Cat(c.color,x,y,140,frame,c.facing,c.hp<=0?Mathf.Max(.15f,1-c.deadTime*1.8f):1,phase=="dash"?4*c.facing:c.stun>0?-9*c.facing:0);
    if(c.hp>0){p.Bar(x-28,y-130,56,c.hp/100f,c.id==0?"#7dd7ad":"#ed9c87",5);if(c.id==0){p.Label("你",x-30,y-165,60,30,16);p.Ring(x,y+4,33,7,3,"#ffd466");}if(c.shield>0)p.Ring(x,y-53,57,68,3,"#a2ecfff0");if(c.power>0)p.Line(x-18,y-3,x+32,y-4,3,"#ee835b");}
   }
   foreach(var f in fx)CatEffects.Impact(p,f.x-camera,baseY+f.y,f.age,f.blocked,f.power);
   if(this.phase=="countdown"){p.Oval(300,355,110,110,"#fff9e9ef");p.Label(Mathf.CeilToInt(countdown).ToString(),240,295,120,120,65,"#c38634");}
  }
 }
